      const id=decodeURIComponent(parts[1]||'');if(!validCompany(id))throw Error('Select a valid company reference.');
      const section=parts[2]||'overview';if(!['overview','entries','trial-balance','register','import'].includes(section))throw Error('Unknown company book view.');
