      el.innerHTML=`<p>This changes only ${esc(ctx.id)} in NXT parallel books. QuickBooks remains authoritative. ${kind==='reverse'?'The server appends an exact opposite entry; the original is retained. One reversal is allowed per target.':kind==='lock'?'The lock only advances; this workflow has no unlock action.':'Use an independently reviewed balanced adjustment; source records remain unchanged.'}</p><p class="integrity">Expected current head ${esc(ctx.detail.head_sha256)}${entry?'<br>Reversal target '+esc(entry):''}</p>${target?'<h3>Exact reversing lines</h3><table><thead><tr><th>Company account</th><th>Reversal debit</th><th>Reversal credit</th></tr></thead><tbody>'+target.lines.map(l=>'<tr><td>'+esc(l.account_id)+'</td><td>'+amount(l.credit_cents)+'</td><td>'+amount(l.debit_cents)+'</td></tr>').join('')+'</tbody></table>':''}<form data-native-book><label>Operator label<input name="operator_label" required maxlength="240"></label><label>${kind==='lock'?'Lock through':'Entry date'}<input name="date" type="date" required></label><label>${kind==='lock'?'Lock note':'Entry memo'}<textarea name="memo" required maxlength="2000"></textarea></label>${kind==='journal'?'<div data-journal-lines>'+line()+line()+'</div><button type="button" class="btn sm" data-add-line>Add line</button>':''}<label class="book-check"><input type="checkbox" name="confirmed" required><span>I reviewed this company, exact action and current receipt and authorize this NXT-only operation.</span></label><p class="book-error" role="alert"></p><div class="row"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Review and authorize operation</button></div></form>`;
      el.querySelector('[data-close]').onclick=()=>close();const add=el.querySelector('[data-add-line]');if(add)add.onclick=()=>{if(el.querySelectorAll('.book-journal-line').length<500)el.querySelector('[data-journal-lines]').insertAdjacentHTML('beforeend',line());};
